// Minimum cost over induced red matchings: footprint intersection plus a transversal of blue (k-3)-cliques outside the union. Output optimal deletion mask and corners, plus minimum raw overlap.
use std::io::{self,BufRead};
fn clique(a:&[u64],mut p:u64,t:u32,q:u64)->u64{if t==0{return q}while p.count_ones()>=t{let j=p.trailing_zeros()as usize;let b=1<<j;p^=b;let s=clique(a,p&!a[j],t-1,q|b);if s!=0{return s}}0}
fn hit(a:&[u64],p:u64,t:u32,b:u32)->Option<u64>{let mut q=clique(a,p,t,0);if q==0{return Some(0)}if b==0{return None}while q!=0{let v=q&q.wrapping_neg();q^=v;if let Some(s)=hit(a,p^v,t,b-1){return Some(s|v)}}None}
fn main(){let k:u32=std::env::args().nth(1).unwrap().parse().unwrap();for l in io::stdin().lock().lines(){let s=l.unwrap();let b=s.as_bytes();let n=(b[0]-63)as usize;let mut a=vec![0u64;n];let mut es=vec![];let mut h=0;for j in 0..n{for i in 0..j{if (b[1+h/6]-63)>>(5-h%6)&1!=0{a[i]|=1<<j;a[j]|=1<<i;es.push((i,j))}h+=1}}let f=(1u64<<n)-1;let es:Vec<_>=es.iter().map(|&(i,j)|(1u64<<i|1u64<<j,a[i]|a[j])).collect();let mut bins=vec![vec![];n];for(i,&(x,b))in es.iter().enumerate(){for &(y,c) in &es[..i]{if x&c!=0||y&b!=0{continue}let d=b&c;bins[d.count_ones() as usize].push((x,y,d,f&!(b|c)))}}let min=bins.iter().position(|xs|!xs.is_empty());if let Some(lo)=min{'outer:for budget in lo..=n{for t in lo..=budget.min(n-1){for &(x,y,d,p) in &bins[t]{if let Some(s)=hit(&a,p,k-3,(budget-t)as u32){assert_eq!((s|d).count_ones()as usize,budget);println!("{} {} {} {} {}",lo,budget,x,y,s|d);break 'outer}}}}}else{println!("-1 -1 0 0 0")}}}
